cd /testbed && python3 - <<'PY'
from pathlib import Path
p = Path('tests/src/unit-udt.cpp')
s = p.read_text()
s = s.replace('#include <map>\n', '#include <cstdint>\n#include <limits>\n#include <map>\n', 1)
marker = 'TEST_CASE("basic usage" * doctest::test_suite("udt"))\n'
test = '''TEST_CASE("enum serialization preserves underlying signedness" * doctest::test_suite("udt"))
{
    SECTION("unsigned 64-bit enum")
    {
        enum class book_id : std::uint64_t {};
        const std::uint64_t values[] =
        {
            0, 42, std::uint64_t(1) << 63,
            (std::numeric_limits<std::uint64_t>::max)() - 1,
            (std::numeric_limits<std::uint64_t>::max)()
        };
        for (const auto value : values)
        {
            const auto id = static_cast<book_id>(value);
            const json j = id;
            CHECK(j.is_number_unsigned());
            CHECK(j.get<std::uint64_t>() == value);
            CHECK(j.dump() == json(value).dump());
            CHECK(j.get<book_id>() == id);

            json assigned = "previous value";
            assigned = id;
            CHECK(assigned.is_number_unsigned());
            CHECK(assigned == j);
        }

        const auto large_id = static_cast<book_id>(std::uint64_t(1) << 63);
        CHECK(json(large_id) > 0u);
        CHECK(to_string(json(large_id)) == "9223372036854775808");
        CHECK(json(large_id).is_number_unsigned());
    }

    SECTION("signed 64-bit enum")
    {
        enum class signed_id : std::int64_t {};
        const std::int64_t values[] =
        {
            (std::numeric_limits<std::int64_t>::min)(), -42, 0, 42,
            (std::numeric_limits<std::int64_t>::max)()
        };
        for (const auto value : values)
        {
            const auto id = static_cast<signed_id>(value);
            const json j = id;
            CHECK(j.type() == json::value_t::number_integer);
            CHECK(j.get<std::int64_t>() == value);
            CHECK(j.dump() == json(value).dump());
            CHECK(j.get<signed_id>() == id);
        }
    }

    SECTION("narrow unsigned enum")
    {
        enum class unsigned_byte : std::uint8_t { max = 255 };
        const json j = unsigned_byte::max;
        CHECK(j.is_number_unsigned());
        CHECK(j == 255u);
        CHECK(j.dump() == "255");
    }

    SECTION("narrow signed enum")
    {
        enum class signed_byte : std::int8_t { min = -128 };
        const json j = signed_byte::min;
        CHECK(j.type() == json::value_t::number_integer);
        CHECK(j == -128);
        CHECK(j.dump() == "-128");
    }

    SECTION("unscoped unsigned enum")
    {
        enum unsigned_id : std::uint64_t { large_id = std::uint64_t(1) << 63 };
        const json j = large_id;
        CHECK(j.is_number_unsigned());
        CHECK(j.dump() == "9223372036854775808");
    }
}

'''
assert s.count(marker) == 1
p.write_text(s.replace(marker, test + marker, 1))
